import { Stack } from "@/shared/ui/layout/Stack";
import { Row } from "@/shared/ui/layout/Row";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";
import { Chip } from "@/shared/ui/data/Chip";

const NPM = "#cb3837";
const ecoColor = (eco) => (eco === "cargo" ? "var(--warn)" : NPM);

function pill(text, color, opts = {}) {
  const t = opts.tint ?? 86;
  return (
    <Chip color={color} radius={4} padding="2px 6px" fontSize={opts.fs ?? 8.5}
      bgAlpha={t} borderAlpha={t - 14} style={{ fontWeight: 600, whiteSpace: "nowrap" }}>
      {text}
    </Chip>
  );
}

function DepRow({ d, registries }) {
  const isPrivate = !!(d.source && registries[d.source]);
  const verColor = d.version ? "var(--fg-dim)" : "var(--warn)";
  const ecoC = isPrivate ? "var(--violet)" : ecoColor(d.ecosystem);
  return (
    <Row align="baseline" gap={8}>
      <Chip color={ecoC} radius={4} padding="2px 5px" fontSize={8} bgAlpha={84} borderAlpha={70} style={{ flexShrink: 0, fontWeight: 600 }}>{d.ecosystem}</Chip>
      <Box style={{ flex: 1, minWidth: 0 }}>
        <Text mono weight={600} size={10.5} style={{ color: "var(--fg)" }}>{d.name}</Text>
        <Text mono weight={500} size={10.5} style={{ color: verColor }}>{d.version ? `@${d.version}` : "@latest"}</Text>
        {d.sharedWith.length > 0 && <Box as="span" style={{ marginLeft: 6 }}>{pill(`↔ shared · ${d.sharedWith.join(", ")}`, "var(--success)")}</Box>}
        {isPrivate && <Box as="span" style={{ marginLeft: 6 }}>{pill("private", "var(--violet)")}</Box>}
        {d.dev && <Box as="span" style={{ marginLeft: 6 }}>{pill("dev", "var(--violet)")}</Box>}
        {d.why && <Text as="div" weight={500} size={9.5} tone="dim" style={{ fontFamily: "var(--sans)", marginTop: 1 }}>{d.why}</Text>}
      </Box>
    </Row>
  );
}

// Preview-only stand-in for `sharedRepoDependencies(dependencies, registries, repoStreams)` (from
// `@/features/planner/issues/dependencyStreams`, a multi-file computation pipeline unresolvable in this
// sandbox) — a precomputed SAMPLE result matching the real `SharedRepoDeps` shape. The preview needs the
// SHAPE, not the algorithm.
const SAMPLE_VIEW = {
  repo: "northwind-api",
  streams: ["worker-1", "worker-2"],
  byStream: [
    { stream: "worker-1", empty: false, deps: [
      { name: "zod", ecosystem: "npm", version: "3.23.8", sharedWith: ["worker-2"], dev: false, why: "request/response validation" },
      { name: "vitest", ecosystem: "npm", version: "1.6.0", sharedWith: [], dev: true },
    ] },
    { stream: "worker-2", empty: false, deps: [
      { name: "zod", ecosystem: "npm", version: "3.23.8", sharedWith: ["worker-1"], dev: false },
      { name: "@acme/internal-auth", ecosystem: "npm", version: "2.1.0", source: "acme-registry", sharedWith: [], dev: false, why: "shared auth middleware" },
    ] },
  ],
  registries: [
    { key: "npm", name: "npm", private: false },
    { key: "acme-registry", url: "npm.acme.dev", scope: "@acme", auth: "token", private: true },
  ],
  total: 3,
};
const SAMPLE_REGISTRIES = { "acme-registry": { url: "npm.acme.dev", scope: "@acme", auth: "token" } };
const SAMPLE_AGENT = { id: "worker-1", name: "worker-1", repo: "northwind-api", color: "var(--accent)" };

export function StreamSharedDeps({
  a = SAMPLE_AGENT, agents = [], dependencies = [], registries = SAMPLE_REGISTRIES,
}) {
  // sharedRepoDependencies(dependencies, registries, repoStreams) is stubbed above — its real inputs
  // stay real props (agents/dependencies/registries), but the derived view is the fixed sample.
  const view = SAMPLE_VIEW;
  if (!view) {
    return (
      <Row gap={7} style={{ padding: "8px 10px", background: "var(--bg-elev)", border: "1px solid var(--border-soft)", borderRadius: 7 }}>
        <Text mono size={11} tone="dim">◴</Text>
        <Text mono weight={500} size={9.5} tone="dim">
          {a.repo ? `${a.repo} is yours alone — its deps stay agent-managed.` : "No repo assigned to this stream."}
        </Text>
      </Row>
    );
  }

  const me = a.id ?? a.name;
  const others = view.streams.filter((s) => s !== me);
  const mine = view.byStream.find((g) => g.stream === me);

  return (
    <Stack gap={11}>
      <Row gap={8} wrap align="baseline">
        <Text mono weight={600} size={11} style={{ color: "var(--fg)" }}>{view.repo}</Text>
        <Box as="span" pad={[2, 6]} bg="var(--bg-elev2)" border radius={4} style={{ fontFamily: "var(--mono)", fontWeight: 500, fontSize: 9, color: "var(--fg-muted)" }}>{view.streams.length} streams</Box>
        {others.length > 0 && <Text mono weight={500} size={9.5} tone="dim">shared with {others.join(", ")}</Text>}
      </Row>

      {view.registries.length > 0 && (
        <Row wrap gap={6} align="center">
          <Text mono weight={600} size={8} tone="dim" style={{ letterSpacing: ".08em", textTransform: "uppercase" }}>registries</Text>
          {view.registries.map((g) => g.private
            ? <Box as="span" key={g.key}>{pill(`${g.url} · ${g.scope ?? ""} · auth ${g.auth ?? "—"}`, "var(--violet)", { tint: 86 })}</Box>
            : <Box as="span" key={g.key}>{pill(`${g.name} · public`, NPM, { tint: 88 })}</Box>)}
        </Row>
      )}

      {!mine || mine.empty ? (
        <Text as="div" mono weight={500} size={9.5} tone="dim" style={{ lineHeight: 1.5 }}>
          No build deps of your own — you hold the reconciled lock for this repo.
        </Text>
      ) : (
        <Stack gap={8} style={{ paddingLeft: 12, borderLeft: `1px solid color-mix(in oklch, ${a.color ?? "var(--accent)"}, transparent 80%)` }}>
          {mine.deps.map((d, j) => <DepRow key={d.name + j} d={d} registries={registries} />)}
        </Stack>
      )}

      <Text as="div" weight={500} size={9.5} tone="dim" style={{ fontFamily: "var(--sans)", lineHeight: 1.5 }}>
        Per-stream deps reconcile into the repo's single <Text mono tone="muted">package.json</Text> / <Text mono tone="muted">Cargo.toml</Text> and are inlined into every agent on the repo.
      </Text>
    </Stack>
  );
}
